desired = {"sg-web": {"ingress": ["443/0.0.0.0/0"]},
           "asg-api": {"min": 6, "max": 60, "type": "m7a.xlarge"}}
actual = {"sg-web": {"ingress": ["443/0.0.0.0/0", "22/0.0.0.0/0"]},
          "asg-api": {"min": 6, "max": 60, "type": "m5.xlarge"},
          "ec2-temp": {}}
for name in sorted(desired.keys() | actual.keys()):
    if name not in actual:
        print("없음  ", name)
    elif name not in desired:
        print("코드밖", name)
    else:
        for k in desired[name]:
            if desired[name][k] != actual[name].get(k):
                print("바뀜  ", name, k, desired[name][k], "->", actual[name].get(k))
# 바뀜   asg-api type m7a.xlarge -> m5.xlarge
# 코드밖 ec2-temp
# 바뀜   sg-web ingress ['443/0.0.0.0/0'] -> ['443/0.0.0.0/0', '22/0.0.0.0/0']
